import manifest from "./imagery-manifest.json";

/**
 * Static satellite imagery registry. Images are stitched Esri World Imagery
 * (the same source The Aerial uses) generated by scripts/fetch-imagery.mjs;
 * the manifest carries each image's exact geographic bounds so pins project
 * accurately. Attribution: Esri, Maxar, Earthstar Geographics, and the GIS
 * User Community.
 */

export type MapImageId = keyof typeof manifest;

export interface MapImage {
  id: string;
  src: string;
  width: number;
  height: number;
  bounds: { west: number; east: number; north: number; south: number };
}

export const mapImages = manifest as Record<MapImageId, MapImage>;

const mercY = (lat: number) =>
  Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));

/** Project lat/lon to pixel coordinates within a map image. */
export function projectToImage(
  img: MapImage,
  lat: number,
  lon: number
): { x: number; y: number; inside: boolean } {
  const { west, east, north, south } = img.bounds;
  const x = ((lon - west) / (east - west)) * img.width;
  const y =
    ((mercY(north) - mercY(lat)) / (mercY(north) - mercY(south))) * img.height;
  const inside = x >= 0 && x <= img.width && y >= 0 && y <= img.height;
  return { x, y, inside };
}

export interface GeoPin {
  label: string;
  lat: number;
  lon: number;
  major?: boolean;
  desktopOnly?: boolean;
  /** Place the label on this side of the dot (default: right). */
  side?: "left" | "right";
}

/** Verified coordinates for the places Raegan serves. */
export const coastPins: GeoPin[] = [
  { label: "Fernandina Beach", lat: 30.6697, lon: -81.4626 },
  { label: "Historic District", lat: 30.6685, lon: -81.4615, desktopOnly: true, side: "left" },
  { label: "Crane Island", lat: 30.6135, lon: -81.473, major: true, side: "left" },
  { label: "Amelia Island", lat: 30.58, lon: -81.444, major: true },
  { label: "Summer Beach", lat: 30.5942, lon: -81.4447, desktopOnly: true, side: "right" },
  { label: "Amelia Island Plantation", lat: 30.527, lon: -81.45, desktopOnly: true, side: "left" },
  { label: "Wildlight", lat: 30.6266, lon: -81.6408 },
  { label: "Yulee", lat: 30.633, lon: -81.5815, desktopOnly: true },
];

export function pinFor(label: string): GeoPin | undefined {
  return coastPins.find((p) => p.label === label);
}

