export function landmark(name: string): { name: string; lat: number; lon: number } | undefined {
  return LANDMARKS.find((l) => l.name === name);
}

/** A close, slightly pitched frame on any point. */
export function closeView(
  lat: number,
  lon: number,
  zoom = 13.4,
  pitch = 52,
  bearing = -18
): MapView {
  return { center: [lon, lat], zoom, pitch, bearing };
}
